// Ohio Union North Garage-inspired simulation: one calibration per CCTV camera (CAM-01…CAM-08),
// each containing ONLY the bays that camera owns, generated by projecting the owned bays' 3D floor
// corners through the camera (the same method as generate-showcase-calibration.mjs).
//   node scripts/generate-ohio-calibration.mjs           write
//   node scripts/generate-ohio-calibration.mjs --check   fail if the committed files drift
// Static geometry only: never imports the world, traffic, vehicles, ground truth or evaluation.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { PerspectiveCamera, Vector3 } from 'three';
import { poseEuler } from '../apps/simulator/src/camera/pose.ts';
import { FLOOR_Y, OHIO_BAYS, OHIO_CAMERAS, ohioOwnedBays } from '../apps/simulator/src/ohio/layout.ts';

const VERSION = 'ohio-union-v1';

function project(pose, bays) {
  const camera = new PerspectiveCamera(pose.fov, pose.width / pose.height, 0.1, 400);
  camera.position.set(...pose.position);
  camera.rotation.set(...poseEuler(pose), 'YXZ');
  camera.updateProjectionMatrix();
  camera.updateMatrixWorld();
  const polygons = {};
  const pixels = {};
  const unobservable = [];
  for (const bay of bays) {
    const p = bay.corners.map((c) => new Vector3(...c).project(camera));
    if (p.some((q) => q.z < -1 || q.z > 1 || Math.abs(q.x) > 1 || Math.abs(q.y) > 1)) {
      unobservable.push(bay.id);
      continue;
    }
    polygons[bay.id] = p.map((q) => ({ x: Number(((q.x + 1) / 2).toFixed(9)), y: Number(((1 - q.y) / 2).toFixed(9)) }));
    pixels[bay.id] = polygons[bay.id].map(({ x, y }) => [Math.round(x * pose.width * 10) / 10, Math.round(y * pose.height * 10) / 10]);
  }
  return { polygons, pixels, unobservable };
}

// Every bay is owned by exactly one camera; every camera owns one half-row.
const owners = new Map();
for (const b of OHIO_BAYS) {
  if (owners.has(b.id)) throw new Error(`bay ${b.id} has two owners`);
  owners.set(b.id, b.owner);
}

const calibrations = OHIO_CAMERAS.map((cam) => {
  const bays = ohioOwnedBays(cam.id);
  const { polygons, pixels, unobservable } = project(cam.pose, bays);
  if (unobservable.length) throw new Error(`${cam.id} cannot see its own bays: ${unobservable.join(',')}`);
  return {
    version: `${VERSION}-${cam.id}`,
    camera_id: cam.id,
    pose: cam.pose,
    projection: `Three.js PerspectiveCamera / YXZ / owned bay floor corners at y=${FLOOR_Y} m projected through ${cam.label}`,
    image: { width: cam.pose.width, height: cam.pose.height },
    owned_bays: bays.map((b) => b.id),
    polygons,
    unobservable,
    bays_3d: Object.fromEntries(bays.map((b) => [b.id, { row: b.row, level: b.level, corners: b.corners }])),
    pixels,
  };
});

// Driver plan: each bay's floor rectangle, normalised to the parking area (x 0.6–58.8, z 0.2–36).
const PX = 0.6;
const PW = 58.2;
const PZ = 0.2;
const PD = 35.8;
const plan = (b) => ({
  x: +((b.corners[0][0] - PX) / PW).toFixed(4),
  y: +((b.corners[0][2] - PZ) / PD).toFixed(4),
  w: +(b.width / PW).toFixed(4),
  h: +(b.depth / PD).toFixed(4),
});
const facility = {
  // Same facility id as the other demo garages: the driver app and the demo scenario read garage-01.
  facility_id: 'garage-01',
  name: 'Ohio Union North Garage-inspired simulation (72 spaces)',
  address: null,
  is_simulated: true,
  levels: [{ level_id: 'L1', name: 'Level 1', ordinal: 0 }],
  spaces: OHIO_BAYS.map((b) => ({ space_id: b.id, level_id: 'L1', designation: 'standard', plan: plan(b) })),
  cameras: calibrations.map((c) => {
    const cam = OHIO_CAMERAS.find((x) => x.id === c.camera_id);
    return {
      camera_id: c.camera_id,
      level_id: 'L1',
      name: `${cam.label} · row ${cam.row} ${cam.module} CCTV`,
      kind: 'virtual',
      watches: c.owned_bays,
      polygons: c.polygons,
    };
  }),
};

// Demo-only description of the site, read by the demo status route and shown on the driver page.
const site = {
  site_id: 'ohio-union',
  title: 'Ohio Union North Garage-inspired simulation',
  tag: 'Simulated · inspired by, not a digital twin',
  disclaimer: 'Inspired by a campus parking deck. Not an official or exact digital twin; no real OSU data. Bays, cameras and traffic are simulated.',
  spaces: OHIO_BAYS.length,
  cameras: OHIO_CAMERAS.length,
  rows: ['A', 'B', 'C', 'D'],
  bays_per_row: 18,
  spine_after: 9,
};

const dir = new URL('../packages/shared/calibration/ohio-union/', import.meta.url);
mkdirSync(dir, { recursive: true });
const outputs = [['facility.json', facility], ['site.json', site], ...calibrations.map((c) => [`${c.camera_id}.json`, c])];
for (const [name, data] of outputs) {
  const path = new URL(name, dir);
  const text = JSON.stringify(data, null, 2) + '\n';
  if (process.argv.includes('--check')) {
    if (readFileSync(path, 'utf8') !== text) throw new Error(`ohio-union calibration drift: ${name} (run node scripts/generate-ohio-calibration.mjs)`);
  } else writeFileSync(path, text);
}
console.log(calibrations.map((c) => `${c.camera_id}: ${Object.keys(c.polygons).length} bays`).join(' · '), `· ${OHIO_BAYS.length} total`);
